INSERT INTO tb_nlcf_collect (
    collect_id
    , request_url
    , page_no
    , num_of_rows
    , result_code
    , result_msg
    , success_yn
    , error_message
    , collected_count
    , raw_response
    , reg_dt
)
VALUES (
    #{collectId}
    , #{requestUrl}
    , #{pageNo}
    , #{numOfRows}
    , #{resultCode}
    , #{resultMsg}
    , #{successYn}
    , #{errorMessage}
    , #{collectedCount}
    , #{rawResponse}
    , CURRENT_TIMESTAMP
)


INSERT INTO tb_nlcf_fairytale (
    fairytale_id
    , collect_id
    , title
    , alternative_title
    , creator
    , reg_date_raw
    , collection_db
    , subject_category
    , subject_keyword
    , extent
    , description
    , spatial_coverage
    , temporal_info
    , person_info
    , language
    , source_title
    , reference_identifier
    , rights_info
    , copyright_others
    , content_url
    , contributor
    , use_yn
    , reg_dt
    , upd_dt
)
VALUES (
    #{fairytaleId}
    , #{collectId}
    , #{title}
    , #{alternativeTitle}
    , #{creator}
    , #{regDate}
    , #{collectionDb}
    , #{subjectCategory}
    , #{subjectKeyword}
    , #{extent}
    , #{description}
    , #{spatialCoverage}
    , #{temporal}
    , #{person}
    , #{language}
    , #{sourceTitle}
    , #{referenceIdentifier}
    , #{rights}
    , #{copyrightOthers}
    , #{url}
